const INDEX: Record<Lang, number> = { pt: -1, "pt-PT": 5, es: 1, en: 0, fr: 2, it: 3, de: 4 };

/** Traduz um texto de interface escrito em pt-BR. Retorna o original se não houver tradução. */
export function translateMicrocopy(source: string, lang: Lang): string {
  if (lang === "pt") return source;
  const row = TABLE[source.trim()];
  if (!row) return lookupUi(source.trim(), lang) ?? source;
  if (lang === "pt-PT") return row[5] ?? source;
  const i = INDEX[lang];
  return row[i] ?? source;
}

export function hasMicrocopy(source: string): boolean {
  return Boolean(TABLE[source.trim()]);
}
